package com.srm.inventory.controller;
import com.srm.inventory.entity.Product; import com.srm.inventory.service.ProductService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController { private final ProductService service; public ProductController(ProductService s){service=s;} @GetMapping public List<Product> list(@RequestParam(required=false) String q,@RequestParam(required=false) Boolean lowStock){return service.list(q,lowStock);} @GetMapping("/{id}") public Product get(@PathVariable Long id){return service.get(id);} @PostMapping public ResponseEntity<Product> create(@Valid @RequestBody Product p){return ResponseEntity.status(HttpStatus.CREATED).body(service.save(p));} @PutMapping("/{id}") public Product update(@PathVariable Long id,@Valid @RequestBody Product p){p.setId(id);return service.save(p);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
